[25]="小世界稳定值-{num1}",
[26]="获得宗门状态：<color=#549327>如日方升（小世界人口 +10%），持续24小时</color>",
[27]="<color=#C55A11>{dname1}</color>发现偷吃灵草的小兽，追逐至一处洞穴，发现其中储藏了不少灵草，顺手收归库房，<color=#0070C0>灵草产量+{num1}</color>",
[28]="<color=#C55A11>{dname1}</color>以神识发现灵田中暗藏的害虫，以法力尽数震碎，将其化作养料，灵草产量不减反增，<color=#0070C0>灵草产量+{num1}</color>",
[29]="<color=#C55A11>{dname1}</color>突发奇想，尝试使用特调绿液灌溉灵草，灵草长势惊人，<color=#0070C0>产量+{num1}</color>",
[30]="<color=#C55A11>{dname1}</color>尝试将部分灵草拔高数寸，且看长势良好，岂料次日灵植纷纷枯死，<color=#ff5252>灵草产量-{num1}</color>",
[31]="药田近日虫害加剧，<color=#C55A11>{dname1}</color>费尽心思也无法尽除，<color=#ff5252>灵草产量-{num1}</color>",
[32]="<color=#C55A11>{dname1}</color>尝试改良灵土五行偏重，颇有成效，<color=#0070C0>灵草产量+{num1}</color>，<color=#C55A11>{dname1}</color><color=#0070C0>培植经验+{num2}</color>",
[33]="<color=#C55A11>{dname1}</color>在灵田翻土时忽见一处灵气聚而不散，刨地三尺后发现乃是一件{item1}，便将其收归库房",
[34]="<color=#C55A11>{dname1}</color>在灵田除草时发现一奇形怪状的瓶子，瓶内阵阵异香散发，打开一看发现了{item1}",
[35]="<color=#C55A11>{dname1}</color>种植灵草时边种边吃，以致<color=#ff5252>灵草产量-{num1}</color>，但修为也精进不少，<color=#0070C0>境界修为+{num2}</color>",
[36]="<color=#C55A11>{dname1}</color>种植灵草时，悄咪咪的中饱私囊，<color=#ff5252>灵草产量-{num1}</color>",
[37]="<color=#C55A11>{dname1}</color>巧用金属性功法收集灵木，事半功倍，<color=#0070C0>灵木产量+{num1}</color>",
[38]="<color=#C55A11>{dname1}</color>发现灵木生长缓慢，神识探查之下发现暗藏蛀虫，以金相功法尽数除之，灵木无恙更添养料，<color=#0070C0>灵木产量+{num1}</color>",
[39]="<color=#C55A11>{dname1}</color>在林场中发现一罕见灵兽，几番设伏捕捉却屡屡失败，徒耗时日，<color=#ff5252>灵木产量-{num1}</color>",
[40]="一道金雷突然落入林场，燃起大火，<color=#C55A11>{dname1}</color>尝试各种手段也无法灭火，只能待火势自行熄灭，<color=#ff5252>灵木产量-{num1}</color>",
[41]="<color=#C55A11>{dname1}</color>在林地中发现一只寻宝兽，沿路追踪时在一处树根之下发现埋藏的{item1}，小兽转眼已不知所踪",
[42]="<color=#C55A11>{dname1}</color>在林地巡视时遇见一受困小狐，心生恻隐将其释放，小狐跑远之时竟化作人形，娇笑间抛出数枚{item1}相赠",
[43]="<color=#C55A11>{dname1}</color>砍伐灵木时，悄咪咪的中饱私囊，<color=#ff5252>灵木产量-{num1}</color>",
