[45]="<color=#C55A11>{dname1}</color>查探灵脉时忽遇地龙翻身，险些丢掉性命，祸福相依之下发现地脉中蕴含大量灵矿！<color=#0070C0>矿石产量+{num1}</color>，<color=#C55A11>{dname1}</color><color=#ff5252>负伤值+{num2}</color>",
