[47]="<color=#C55A11>{dname1}</color>于岩壁中发现一面古老石碑，其上浮现出金色文字，似是聚灵之法，观摩之下不禁心神迷茫，陷入顿悟，醒来之时石碑却已碎裂，化作一地碎石",
[48]="<color=#C55A11>{dname1}</color>在矿坑中意外发现一处地下密室，一番探索后寻获{item1}",
[49]="<color=#C55A11>{dname1}</color>采集矿石时，发现一个埋藏的玉盒，将其打开后发现其中装满了灵石，获得{item1}",
[50]="<color=#C55A11>{dname1}</color>采集矿石时，悄咪咪的中饱私囊，<color=#ff5252>矿石产量-{num1}</color>",
[51]="<color=#C55A11>{dname1}</color>于岩壁中发现一枚古怪铁片，伸手去取时铁片竟产生强大吸扯之力，<color=#C55A11>{dname1}</color>一身灵力被尽数吸走，晕厥不醒，醒来之时铁片不翼而飞",
[52]="<color=#C55A11>{dname1}</color>炼制玄铁时灵力控制得当，炉火呈纯青之色，<color=#0070C0>玄铁产量+{num1}</color>",
[53]="<color=#C55A11>{dname1}</color>炼制玄铁时尝试更改聚火法阵，伴随着冲天的火光和焦糊味，<color=#0070C0>玄铁产量+{num1}</color>，<color=#C55A11>{dname1}</color><color=#0070C0>负伤值+{num2}</color>",
[54]="<color=#C55A11>{dname1}</color>尝试融入多种地火炼制玄铁，恐怖的火行灵力在炼器阁中激荡，险些失控，幸而炼器过程有惊无险，<color=#0070C0>玄铁产量+{num1}</color>",
