[62]="<color=#C55A11>{dname1}</color>炼制符纸时贪图便捷，以火法干燥纸张，却误把符纸点燃，大批符纸付之一炬...<color=#ff5252>符纸产量-{num1}</color>",
[63]="<color=#C55A11>{dname1}</color>在炼制符纸时福至心灵，炼制成功率喜人，<color=#0070C0>符纸产量+{num1}</color>，<color=#0070C0>制符经验+{num2}</color>",
[64]="<color=#C55A11>{dname1}</color>灰头灰脸的走出了符箓坊，脸上露出一抹笑容，看着手上攥着几张优质符纸，颇有心得感悟，<color=#0070C0>制符经验+{num1}</color>",
[65]="<color=#C55A11>{dname1}</color>炼制符纸时心中有感，提笔画于符纸之上，完成最后一笔之时，画中之物竟化为实体，获得{item1}",
[66]="<color=#C55A11>{dname1}</color>借用差事之便练习画符，在报废了多张符纸后，竟画成{item1}！<color=#C55A11>{dname1}</color><color=#0070C0>制符经验提升{num1}</color>",
