[69]="<color=#C55A11>{dname1}</color>尝试修改阵石炼制之法，却致阵石灵力运转不畅，废品连连，<color=#ff5252>本次阵石产量-{num1}</color>，<color=#C55A11>{dname1}</color><color=#0070C0>阵法经验提升{num2}</color>",
[70]="<color=#C55A11>{dname1}</color>炼制阵石时，不慎导致阵法崩溃，在奋不顾身的抢救下，挽回部分损失，<color=#ff5252>阵石产量-{num1}</color>，<color=#ff5252>负伤值+{num2}</color>",
[71]="<color=#C55A11>{dname1}</color>炼制阵石时错把阵图绘制成传送阵法，强光骤然亮起后，一件{item1}出现在阵法中央，缓过神来的<color=#C55A11>{dname1}</color>欣喜的将其收归库房",
