[73]="<color=#C55A11>{dname1}</color>于炼制阵石时灵机一动，以阵石炼制避雷法器，偷偷藏起，<color=#ff5252>阵石产量-{num1}</color>，<color=#C55A11>{dname1}</color><color=#0070C0>境界突破成功率+10%</color>",
[74]="<color=#C55A11>{dname1}</color>对御火之术略有感悟，明知在灵田中施展会殃祸灵药，依然任性而为，引发火情，致使灵田的<color=#0070C0>灵草产量-{num1}</color>",
[75]="<color=#C55A11>{dname1}</color>喜爱萌幼灵兽，私自带入灵田之中，小兽在灵田翻滚踩踏，<color=#C55A11>{dname1}</color>非但不阻止，还笑呵呵看着，导致<color=#0070C0>灵草产量-{num1}</color>",
[76]="<color=#C55A11>{dname1}</color>明知灵植间五行相克，依然将其混种在一起，兴致勃勃地观察植株变化，不出所料，灵草很快枯萎，导致<color=#0070C0>灵草产量-{num1}</color>",
[77]="<color=#C55A11>{dname1}</color>对御火之术略有感悟，明知在林场中施展会殃祸灵木，依然任性而为，引发火情，致使林场的<color=#0070C0>灵木产量-{num1}</color>",
[78]="<color=#C55A11>{dname1}</color>不喜林木杂乱，便施法挪移，将林木排列得工工整整，却致使部分林木无法适应新灵土而枯萎，致使林场的<color=#0070C0>灵木产量-{num1}</color>",
[79]="<color=#C55A11>{dname1}</color>在坊市买下一批灵虫，在林场中放了出去，之后便撒手不管，灵虫四处啃食林木，致使林场的<color=#0070C0>灵木产量-{num1}</color>",
[80]="<color=#C55A11>{dname1}</color>在矿场中掐诀御器，修炼起功法来，手中法诀越来越快，失手将一条矿洞支路击毁，致使矿场的<color=#0070C0>矿石产量-{num1}</color>",
[81]="<color=#C55A11>{dname1}</color>为加快矿石生产，取来数枚爆裂符安置于矿脉上，不多时，轰隆声起，不但没挖出矿石，还将矿脉掩埋，致使矿场的<color=#0070C0>矿石产量-{num1}</color>",
[82]="<color=#C55A11>{dname1}</color>为对御水之术略有感悟，明知在炼器阁中施展会浸染矿物，依然任性而为，致使少量矿物被毁，致使炼器阁的<color=#0070C0>玄铁产量-{num1}</color>",
[83]="<color=#C55A11>{dname1}</color>为感悟火行之力，在炼器阁中引动地火，如此毛躁行径，引发地火汹涌而出，致使炼器阁一时无法使用，致使炼器阁的<color=#0070C0>玄铁产量-{num1}</color>",
[84]="<color=#C55A11>{dname1}</color>翻看杂书，得知符箓绘制之法，便擅自取走符箓坊的符纸当做练习，耗费不少符纸却毫无成果，致使符箓坊的<color=#0070C0>符纸产量-{num1}</color>",
