[87]="<color=#C55A11>{dname1}</color>心有杂念，无法静心镌刻阵石，也就越加烦躁，之后竟对天工阁事务有些怄气，擅自毁去些许材料，致使天工阁的<color=#0070C0>阵石产量-{num1}</color>",
[88]="{dname1}突然修为暴涨，渡劫成功率增加{0}",
[89]="<color=#C55A11>{dname1}</color>拍了拍衣服上的灰尘，神清气爽地走出洞府，多日闭关苦修颇有成效！<color=#0070C0>境界修为+{num1}</color>",
