[91]="<color=#C55A11>{dname1}</color>打坐修炼时心神失守，心魔作祟之下灵气逆转，险些道消身死，以致<color=#0070C0>境界修为-{num1}</color>",
[92]="一声惨叫响彻云霄，<color=#C55A11>{dname1}</color>修炼急于求成以致灵力失控，险些伤及元神，<color=#0070C0>境界修为-{num1}</color>，<color=#0070C0>负伤值+{num2}</color>",
[93]="<color=#C55A11>{dname1}</color>观四季风光，日月流转，心意通达之际获得一丝明悟，<color=#0070C0>境界修为+{num1}</color>",
[94]="<color=#C55A11>{dname1}</color>清晨登高望远，观看云海变换之时忽感瓶颈松动，随即打坐入定，一番感悟之下收获颇多，<color=#0070C0>境界突破成功率+5%</color>",
