[97]="<color=#C55A11>{dname1}</color>在雨中御空飞行时忽被天雷击中，气息翻涌之下竟有所感悟，<color=#0070C0>渡劫成功率+5%</color>",
[98]="<color=#C55A11>{dname1}</color>御空飞行时忽被天雷击中，气息翻涌之下不禁破口大骂，随即天地间响起连绵不绝的雷声，<color=#C55A11>{dname1}</color><color=#0070C0>境界修为-{num1}</color>，<color=#0070C0>负伤值+{num2}</color>",
