[100]="<color=#C55A11>{dname1}</color>打坐修炼时睡了过去，一觉醒来顿觉神清气爽，黑眼圈消失无踪，<color=#0070C0>境界修为+{num1}</color>",
[101]="以灵力蒸干身上的汗水，<color=#C55A11>{dname1}</color>感受着体内澎湃的气血之力，多日的炼体苦修颇有成效，<color=#0070C0>炼体经验+{num1}</color>",
[102]="<color=#C55A11>{dname1}</color>与同门因琐事争论大打出手，虽被揍得鼻青脸肿，但体魄打熬颇有成效，<color=#0070C0>炼体经验+{num1}</color>",
[103]="<color=#C55A11>{dname1}</color>修炼时服用偶然所得的怪异丹药，修为非但毫无寸进，更是腹痛难止，<color=#C55A11>{dname1}</color><color=#0070C0>炼体经验-{num1}</color>，<color=#0070C0>负伤值+{num2}</color>",
[104]="<color=#C55A11>{dname1}</color>冒险引下一道天雷淬体，险被轰至飞灰，<color=#0070C0>炼体经验+{num1}</color>，<color=#0070C0>负伤值+{num2}</color>",
[105]="<color=#C55A11>{dname1}</color>近日迷恋药浴不可自拔，灵石俸禄挥霍一空，但体魄打熬却颇有成效，<color=#0070C0>炼体经验+{num1}</color>",
[106]="<color=#C55A11>{dname1}</color>为打熬体魄自封修为，独自前往后山修炼，归来时伤痕累累，但浑身气血颇为旺盛。<color=#C55A11>{dname1}</color><color=#0070C0>炼体经验+{num1}</color>，<color=#0070C0>负伤+{num2}</color>",
[107]="<color=#C55A11>{dname1}</color>使用药浴打熬体魄，好奇心驱使下嘬了一口药液，顿觉五内翻腾，<color=#0070C0>炼体经验-{num1}</color>",
[108]="<color=#C55A11>{dname1}</color>修炼功法时忽有顿悟，闭关数日潜心修行，<color=#0070C0>功法{gfname1}经验+{num1}</color>",
[109]="<color=#C55A11>{dname1}</color>以打扫为由，于藏经阁中翻看典籍，一来二去之下，<color=#0070C0>{gfname1}功法经验+{num1}</color>",
[110]="<color=#C55A11>{dname1}</color>近日功法修炼并无寸进，郁闷之余翻看仙侠小说消遣，竟然触类旁通有所顿悟，<color=#0070C0>功法{gfname1}经验+{num1}</color>",
[111]="<color=#C55A11>{dname1}</color>日复一日刻苦修习<color=#0070C0>{gfname1}</color>，厚积薄发之下终将功法融会贯通，<color=#0070C0>功法经验+{num1}</color>",
[112]="<color=#C55A11>{dname1}</color>在禅院中静修，心念通达之际，忘却怪癖<color=#0070C0>心障</color>",
