[121]="<color=#C55A11>{dname1}</color>在书画铺中练习作画，欲罢不能，获得怪癖<color=#0070C0>强迫症</color>",
[122]="<color=#C55A11>{dname1}</color>在书画铺中练习作画，欲罢不能，获得怪癖<color=#0070C0>拖延症</color>",
[123]="<color=#C55A11>{dname1}</color>终日流连百花坊，对花草灵植见解也日渐加深，<color=#0070C0>培植经验+{num1}</color>",
[124]="<color=#C55A11>{dname1}</color>近日修习音律，心思活络略有所悟，<color=#0070C0>聪慧+{num1}</color>",
