[127]="<color=#C55A11>{dname1}</color>近日于八卦坊中习得少许趋吉避凶之术，<color=#0070C0>机缘+{num1}</color>",
[128]="<color=#C55A11>{dname1}</color>常参观珍兽阁，对御兽之法略有领悟，<color=#0070C0>饲养经验+{num1}</color>",
[129]="<color=#C55A11>{dname1}</color>在玉石铺与掌柜探讨奇石，对地脉学说颇感兴趣，<color=#0070C0>聚灵经验+{num1}</color>",
[130]="近日山下多有妖兽出没，据闻作乱妖兽是一只筑基期铁甲鳄，各地已发布悬赏，诛杀此妖可获得不菲赏金，是否派遣弟子下山降妖？",
