[247]="令出法随，布下十方聚灵大阵，揠苗助长般收获海量灵草灵木资源，致各地灵气失衡，人心动荡。小世界稳定值-15",
[248]="令出法随，探明大量灵石灵矿等矿脉资源，强行征招矿丁加速采集，使得人心动荡。小世界稳定值-15",
[249]="令出法随，使世间海晏河清，万物生发有序，众生恬然自得。小世界稳定值+{num1}",
[250]="令出法随，强行征召人手，日夜不歇，加速符纸绘制，使得人心动荡。小世界稳定值-20",
[251]="令出法随，强行征召劳力，日夜不歇，淬炼大量玄铁。易使人心动荡。小世界稳定值-20",
[252]="令出法随，使世间男女心驰神往皆属情爱之事，夫妻一心求嗣。但将致世人好逸恶劳，易生动荡。小世界稳定值-10",
[253]="令出法随，使世人日夜沉迷修行，一心求仙。但修行入道自有命数，故凡人殒命者多如虫蚁，易生动荡。小世界稳定值-30",
[254]="近日，某杏林世家有一天之骄女，为产妇临盆改良一应措施，此举很快普及各地，人口增长速率+2%，小世界稳定值+{num1}",
[255]="近年，春耕之期皆少见雨水，各地多行求雨祈福之仪，香火值增长速率+2%，小世界稳定值+{num1}",
[256]="近年，各地水患频发，良田受灾，涝不保收，以致粮食减产，饿殍满道，人口增长速率-8%，小世界稳定值-{num1}",
[257]="近年，几大势力斗法愈演愈烈，平民百姓忙于生计，无心祈福，香火值增长速率-8%，小世界稳定值-{num1}",
[258]="今日，南部海域突发海啸，影响甚广，小世界稳定值-{num1},人口数量-{num2}",
[259]="近日，西南地域突发瘟疫，传染极快，影响甚巨，以致人心惶惶，香火值增长速率-5%，小世界稳定值-{num1},人口数量-{num2}",
[260]="近年，气候适宜，各地风调雨顺，盈车嘉穗，百姓丰衣足食，人口增长速率+4%，小世界稳定值+{num1}",
[261]="近年，各地常有神仙显灵的传闻，诸多百姓信誓旦旦，见过仙人下凡泽被一方，香火值增长速率+4%，小世界稳定值+{num1}",
[262]="近年，各地世族相安无事，百姓安居乐业，祈福之风盛行，人口增长速率+3%，香火值增长速率+4%，小世界稳定值+{num1}",
[263]="近日，各地大旱，滴雨未见，以致禾田无收，民不饱腹，百姓节衣缩食，人口增长速率-4%，小世界稳定值-{num1}",
[264]="近年，各地天灾频频，夏多洪涝，冬寒河冰，以致民不聊生，无心祈福，香火值增长速率-4%，小世界稳定值-{num1}",
[265]="今日，东部近海地域台风肆虐，影响甚巨，百姓流离失所，以致人口增长速率-2%，小世界稳定值-{num1},人口数量-{num2}",
[266]="近年，几大杏林世家往来密切，著新药方百余数，惠及各地，人丁兴旺，以致人口增长速率+6%，小世界稳定值+{num1}",
[267]="近年，各地皆是年丰时稔，家家户户硕粮满仓，民间祈福之风大盛，香火值增长速率+6%，小世界稳定值+{num1}",
[268]="近年，世间灵气充裕，几大世族专注自身发展，凡间祈福之风盛行，人口增长速率+4%，香火值增长速率+4%，小世界稳定值+{num1}",
[269]="今日，西北地域突发蝗灾，良田颗粒无收，以致粮食匮乏，各地饥民转徙，人口增长速率-3%，小世界稳定值-{num1}",
[270]="近年，几大势力冲突频频，硝烟四起，各地兵荒马乱，闹得人心惶惶，香火值增长速率-3%，小世界稳定值-{num1},人口数量-{num2}",
[271]="{dname1}与{dname2}因小事起了争执，不欢而散，不久后，{dname2}洞府失窃，丢失不少灵石丹药",
[272]="<color=#ca631d>{dname1}</color>游历归来，见<color=#ca631d>{dname2}</color>在山门冒着寒风等自己，<color=#ca631d>{dname1}</color>心里满是温暖，刺骨寒意顷刻消散；二人好感上升",
[273]="<color=#ca631d>{dname1}</color>除魔有功，得了数枚灵丹，与<color=#ca631d>{dname2}</color>分享，两人于静谧之处双修炼化药力；二人好感上升",
[274]="<color=#ca631d>{dname2}</color>修为陷入瓶颈，<color=#ca631d>{dname1}</color>得知后寻其互述心事，深谈下<color=#ca631d>{dname2}</color>阔然开朗；<color=#ca631d>{dname2}</color>对其好感上升",
[275]="一日，<color=#ca631d>{dname2}</color>见<color=#ca631d>{dname1}</color>与他人一同出行，举止亲昵，<color=#ca631d>{dname2}</color>强忍愤恨黯然离开，心中对其好感下降",
[276]="<color=#ca631d>{dname2}</color>无意间发现<color=#ca631d>{dname1}</color>所写的日记笔录，好奇心驱使下翻看起来，在看到<color=#ca631d>{dname1}</color>字里行间的亲近之意时脸上不由泛起淡淡的笑意；<color=#ca631d>{dname2}</color>对其好感上升",
[277]="<color=#ca631d>{dname1}</color>想起<color=#ca631d>{dname2}</color>平日喜花，便去百花坊买得一束送去，<color=#ca631d>{dname2}</color>看着花；<color=#ca631d>{dname2}</color>对其好感上升",
[278]="<color=#ca631d>{dname2}</color>刚入洞府，<color=#ca631d>{dname1}</color>便端着美酒佳肴前来探望，两人边饮酒边谈论游历趣闻，甚是畅快；<color=#ca631d>{dname2}</color>对其好感上升",
[279]="<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>一同闲逛，忽然有人御剑急来，眼见就要撞上，<color=#ca631d>{dname1}</color>见状立马将其挽住，二人好感上升",
[280]="<color=#ca631d>{dname1}</color>见心仪之人<color=#ca631d>{dname2}</color>与他人亲近，心中愁苦，独自买醉叹道：“医者可医天下人，却不自医”；<color=#ca631d>{dname1}</color>对其好感下降",
[281]="<color=#ca631d>{dname2}</color>刚入洞府，<color=#ca631d>{dname1}</color>便端着美酒佳肴来探望，两人草草聊了几句，<color=#ca631d>{dname2}</color>便借故让其离开；<color=#ca631d>{dname1}</color>对其好感下降",
[282]="<color=#ca631d>{dname1}</color>在礼乐坊报了琴艺班，兴致勃勃地找到<color=#ca631d>{dname2}</color>一展琴艺，呕哑之音折磨得<color=#ca631d>{dname2}</color>修为受损；<color=#ca631d>{dname2}</color>对其好感下降",
[283]="一日，<color=#ca631d>{dname1}</color>看着<color=#ca631d>{dname2}</color>与他人在商业街闲逛，一种天塌的感觉莫名生出，<color=#ca631d>{dname1}</color>对其好感下降",
[284]="<color=#ca631d>{dname2}</color>刚入洞府，<color=#ca631d>{dname1}</color>便端着美酒佳肴前来探望，<color=#ca631d>{dname2}</color>借故自己已辟谷，拒绝了好意；<color=#ca631d>{dname1}</color>对其好感下降",
[285]="<color=#ca631d>{dname2}</color>负伤归来，<color=#ca631d>{dname1}</color>得知后心中焦急，带丹药去探望，不料被拒之门外，放下丹药含泪离开；<color=#ca631d>{dname1}</color>对其好感下降",
[286]="<color=#ca631d>{dname1}</color>偶然间获得一壶佳酿，特意找<color=#ca631d>{dname2}</color>共饮一番，两人把酒言欢，大谈逸闻趣事；二人好感上升",
[287]="<color=#ca631d>{dname1}</color>和<color=#ca631d>{dname2}</color>见夕阳美景无限，二人对起诗来，<color=#ca631d>{dname2}</color>略胜一筹，<color=#ca631d>{dname1}</color>羞恼离去；<color=#ca631d>{dname1}</color>对其好感下降",
[288]="<color=#ca631d>{dname1}</color>近日无心修炼，前往禅院静修，恰巧<color=#ca631d>{dname2}</color>也在此处，二人相视而坐间，说不出的心潮涌动；二人好感上升",
[289]="听闻<color=#ca631d>{dname2}</color>喜好作画，<color=#ca631d>{dname1}</color>在书画铺中购得上等画纸赠予，<color=#ca631d>{dname2}</color>甚是欢喜，对其又多了几分亲昵；二人好感上升",
[290]="<color=#ca631d>{dname1}</color>深研阵法小有所得，去寻<color=#ca631d>{dname2}</color>欲分享喜悦之事，<color=#ca631d>{dname2}</color>却痴痴看着，<color=#ca631d>{dname1}</color>羞得脸红；二人好感上升",
