[433]="<color=#ca631d>{dname1}</color>熬夜研读古籍时，<color=#ca631d>{dname2}</color>“恰好“路过，放下一盏安神茶：“别熬太晚。”<color=#ca631d>{dname1}</color>笑了笑；对其好感上升",
[434]="<color=#ca631d>{dname1}</color>邀<color=#ca631d>{dname2}</color>一同下山历练，<color=#ca631d>{dname2}</color>却摆手拒绝：“这次约了别人，下次吧。”随即转身离去，留其怔在原地，<color=#ca631d>{dname1}</color>失落无比；对其好感下降",
[435]="<color=#ca631d>{dname1}</color>练功走火入魔时，<color=#ca631d>{dname2}</color>虽满脸不耐，仍出手相助：“死了还得替你收尸，麻烦。”<color=#ca631d>{dname1}</color>对其好感上升",
[436]="<color=#ca631d>{dname1}</color>好心提醒<color=#ca631d>{dname2}</color>功法缺陷，却被<color=#ca631d>{dname2}</color>冷声打断：\'管好你自己，别来指手画脚！“<color=#ca631d>{dname1}</color>漠然离去；对其好感下降",
[437]="<color=#ca631d>{dname1}</color>练功岔气，<color=#ca631d>{dname2}</color>立刻运功帮<color=#ca631d>{dname1}</color>梳理经脉，表示：“下次小心些。”二人好感上升",
[438]="<color=#ca631d>{dname1}</color>提议一起研习新功法，<color=#ca631d>{dname2}</color>却皱眉拒绝：“你基础太差，我先教你基本功。”<color=#ca631d>{dname1}</color>顿感无趣；二人好感下降",
[439]="<color=#ca631d>{dname1}</color>下山历练带回灵果，特意给<color=#ca631d>{dname2}</color>留了一颗，<color=#ca631d>{dname2}</color>道谢后小心收进储物袋；二人好感上升",
[440]="<color=#ca631d>{dname1}</color>因伤错过宗门小比，想看<color=#ca631d>{dname2}</color>比试留影。<color=#ca631d>{dname2}</color>表示：“败者何须回顾？”并直接毁了留影石。<color=#ca631d>{dname1}</color>只觉其小气；二人好感下降",
[441]="<color=#ca631d>{dname1}</color>见<color=#ca631d>{dname2}</color>练功不慎岔气，默默递上清心丹，<color=#ca631d>{dname2}</color>虽皱眉，但还是接下；二人好感上升",
[442]="<color=#ca631d>{dname1}</color>耗费半月炼制的清心丹，被<color=#ca631d>{dname2}</color>转手喂了灵兽。还表示此丹和饲料无异。<color=#ca631d>{dname1}</color>感一片真心被践踏；二人好感下降",
[443]="<color=#ca631d>{dname1}</color>遭遇妖兽偷袭，<color=#ca631d>{dname2}</color>飞身格挡，<color=#ca631d>{dname1}</color>瞥见其撕裂的衣袖，到嘴边的呵斥咽了回去，亲自将其送回宗门；对其好感上升",
[444]="<color=#ca631d>{dname2}</color>见<color=#ca631d>{dname1}</color>面色苍白，关切询问是否不适，却被其甩了脸色。<color=#ca631d>{dname2}</color>顿感真心错付；对其好感下降",
[445]="有人正背后诋毁<color=#ca631d>{dname2}</color>，<color=#ca631d>{dname1}</color>恰好听见，冷着脸插话：“<color=#ca631d>{dname2}</color>蠢归蠢，轮不到你们说。”此幕被<color=#ca631d>{dname2}</color>所见；对其好感上升",
[446]="<color=#ca631d>{dname2}</color>见<color=#ca631d>{dname1}</color>与人起了争执，便要上前调节，却不料被<color=#ca631d>{dname1}</color>迁怒呵斥；对其好感下降",
[447]="<color=#ca631d>{dname2}</color>发现<color=#ca631d>{dname1}</color>偷偷给受伤的灵兽包扎，次日<color=#ca631d>{dname1}</color>桌上多了一瓶兽药；二人好感上升",
[448]="<color=#ca631d>{dname1}</color>\"不慎\"打翻<color=#ca631d>{dname2}</color>熬了三天的药汁，<color=#ca631d>{dname2}</color>反手将<color=#ca631d>{dname1}</color>最爱的发簪熔成铁水；二人好感下降",
[449]="<color=#ca631d>{dname2}</color>练武扭伤脚踝，<color=#ca631d>{dname1}</color>边嗔：“冒失鬼。”边蹲身为她敷药揉按，动作轻柔。<color=#ca631d>{dname2}</color>疼得呲牙却偷笑：“幸好有你在。”二人好感上升",
[450]="<color=#ca631d>{dname1}</color>满心期待<color=#ca631d>{dname2}</color>答应同逛坊市的日子，<color=#ca631d>{dname2}</color>却与旁人谈笑下山。<color=#ca631d>{dname1}</color>独坐窗前，摩挲着准备交换的发簪，眼神黯淡；对其好感下降",
[451]="<color=#ca631d>{dname1}</color>见<color=#ca631d>{dname2}</color>咳嗽，默默放下一罐温润花茶在其案头。<color=#ca631d>{dname2}</color>发现后浅笑：“多谢，费心了。“ 两人心头微暖；二人好感上升",
[452]="<color=#ca631d>{dname1}</color>热情邀<color=#ca631d>{dname2}</color>同浴灵泉放松。<color=#ca631d>{dname2}</color>婉拒：“多谢，我习惯独自静修。“<color=#ca631d>{dname1}</color>失落抿唇；对其好感下降",
[453]="暴雨倾盆，<color=#ca631d>{dname2}</color>未带伞被困亭中。<color=#ca631d>{dname1}</color>犹豫片刻，将多余雨具放亭角石凳，快步离开。<color=#ca631d>{dname2}</color>盯着雨具，还是将其拾起；二人好感上升",
[454]="<color=#ca631d>{dname1}</color>见<color=#ca631d>{dname2}</color>脸色苍白，关切问：“可需丹药？” <color=#ca631d>{dname2}</color>立刻竖眉：“假惺惺！管好你自己！”灵力震开靠近的<color=#ca631d>{dname1}</color>；二人好感下降",
[455]="<color=#ca631d>{dname1}</color>提过想看某冷门游记，几日后女“恰好”带来：“喏，翻到了。“ <color=#ca631d>{dname1}</color>真心展颜：“呀！你还记得呀，多谢！“二人好感上升",
[456]="<color=#ca631d>{dname2}</color>反复追问<color=#ca631d>{dname1}</color>不愿多提的私事，眼神关切却紧迫。<color=#ca631d>{dname1}</color>终敛笑：“抱歉，容我静会儿。”转身离开；二人好感下降",
[457]="坊市遇雨，<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>相视一笑，同撑一把伞挤在檐下分食新买灵果，笑语驱散阴霾；二人好感上升",
[458]="<color=#ca631d>{dname1}</color>分享趣事，<color=#ca631d>{dname2}</color>却心不在焉敷衍应和，眼神飘向别处。<color=#ca631d>{dname1}</color>察觉，兴致索然止住话头，便转身离去；二人好感下降",
[459]="<color=#ca631d>{dname2}</color>抱重物过门槛踉跄，<color=#ca631d>{dname1}</color>本能扶了一把。<color=#ca631d>{dname2}</color>虽冷脸却未出恶言。快步离去后，<color=#ca631d>{dname1}</color>微愣；二人好感上升",
[460]="<color=#ca631d>{dname2}</color>的灵兽打翻药圃，<color=#ca631d>{dname1}</color>温言提醒。<color=#ca631d>{dname2}</color>反唇相讥：“多管闲事！我的灵兽轮不到你说。” 二人好感下降",
[461]="<color=#ca631d>{dname1}</color>意外受伤，<color=#ca631d>{dname2}</color>关切询问其伤势，<color=#ca631d>{dname1}</color>虽冷嗤：“死不了。”却对其好感上升",
[462]="<color=#ca631d>{dname2}</color>见<color=#ca631d>{dname1}</color>灵力紊乱欲相助，手未触及便被<color=#ca631d>{dname1}</color>厉喝：“滚开！想害我走火入魔？” 对其好感下降",
[463]="<color=#ca631d>{dname1}</color>摔碎药瓶割伤手，<color=#ca631d>{dname2}</color>递上干净布条。<color=#ca631d>{dname1}</color>夺过自行包扎，对<color=#ca631d>{dname2}</color>好感上升些许",
[464]="<color=#ca631d>{dname2}</color>分享新制点心，<color=#ca631d>{dname1}</color>却直接打翻点心，表示：“谁知道你安的什么心？”双方好感下降",
[465]="<color=#ca631d>{dname1}</color>毛笔滚落<color=#ca631d>{dname2}</color>脚边，<color=#ca631d>{dname2}</color>用鞋尖轻轻将其拨回，<color=#ca631d>{dname1}</color>对其眨巴眨巴眼睛；二人好感上升些许",
[466]="<color=#ca631d>{dname1}</color>离座取水，<color=#ca631d>{dname2}</color>趁机将其蒲团踢开，摆上一堆杂物，<color=#ca631d>{dname1}</color>归来冷笑一声，将杂物扫出门外；二人好感下降",
[467]="返回门中",
[468]="凡人谢礼",
[469]="仙门的大恩大德，小的无以为报，这些是平日里，俺们在山中采集一些罕见药草、灵光金石，希望能对仙师有用",
[470]="收下谢礼",
[471]="心领了，你们更需要",
[472]="听到仙师将庇护一方，那壮汉已激动无言，只剩下连连拜谢，好一会后，弟子们才将他送下山去",
[473]="听到仙师将庇护一方，那壮汉连连拜谢，随后弟子们将他送下山去，此等善举在门内很快传开",
[474]="获得宗门状态：<color=#549327>仁心为善（弟子境界修炼效率 +3%），持续12小时</color>",
[475]="医者求救",
[476]="咳...咳咳...那宵小之辈，修为比我还弱些，否则也不用偷袭这种卑鄙手段了，至于原因，也许，是看中我采到的数味珍稀灵药吧...还请贵宗庇护小女子，逃过此劫...",
[477]="救下此女",
[478]="索要代价，方能庇护",
[479]="来历不明，恕难相助",
[480]="众人将尹芝安顿在后山的一处隐秘位置，随后若无其事走出来，将尹芝赠送的灵药收入库房之中",
[481]="众人将尹芝安顿在后山的一处隐秘位置，随后若无其事出来，将尹芝拿出的灵药收入库房之中",
[482]="尹芝孤独的身影，略显踉跄地飞下山去，不知会去何处藏身",
[483]="寻找女修",
[484]="那个...她...呃...此女潜入我守护的灵药园，偷走了不少珍稀灵药哇，仙友如果知道这女贼的行踪，还望告知",
[485]="没见过什么女修",
[486]="交出躲在后山的女修",
[487]="那黑衣修士脸颊抽动数次，却不好发作，只得转身走开，悄然间，他回头望向宗门，目露凶光，不知在想些什么",
[488]="那黑衣修士虏起尹芝，飞下山去，随后传来一阵猖獗笑声，众人手里拿着此人给的些许灵石，陷入沉默之中",
[489]="尹芝遭到勒索后，便不再信任我等，早已偷偷溜走，众人拿着那黑衣修士给的些许灵石，陷入沉默之中",
[490]="告知女修下山去向",
[491]="那黑衣修士直奔尹芝离去的方向而去，众人收起修士给的些许灵石，不再理会此事",
[492]="麻烦不断",
[493]="你...你们，好！好！只要你们宗门有人单挑胜过我，我就不再追究那女修之事，可敢应战！",
[494]="派弟子单挑",
[495]="我一群挑你一个！",
[496]="韩飞羽将此人丢到山下一处溪水边，收起储物袋，便不再管他死活，转身返回宗门中",
[497]="医者消息",
[498]="在下稳住了那女修伤势，已无性命之忧，但也需要静养伤势，恰好贵门所在，因此想来问问，门中是否有女弟子失踪？",
[499]="她可是名医师？",
[500]="门中弟子都在",
[501]="与此人告别后，众人不禁回想，若当初能多帮一把，那女子也不用受此磨难了。此事很快在门内传开，众弟子心头沉重",
[502]="因此获得宗门状态：<color=#f36666>怅然若失（弟子自行修炼效率 -10%）</color>",
[503]="与此人告别后，众人不禁回想，若当初能多帮一把，那女子也不用受此磨难了。此事不久在门内传开，众弟子心头沉重",
[504]="获得宗门状态：<color=#f36666>怅然若失（弟子自行修炼效率 -10%）</color>，持续12小时",
[505]="获得宗门状态：<color=#f36666>怅然若失（弟子自行修炼效率 -10%），持续12小时</color>",
[506]="医师拜谢",
[507]="小女有一不情之请，多年来颠沛的散修生涯，我常想加入一方宗门，以求安稳修行，小女资质愚钝，但在培植一道略有心得，不知...贵宗能否收我为徒",
[508]="收为弟子",
[509]="遗憾婉拒",
[510]="众人皆是满心欣喜，将尹芝带入宗门之中，尤其三师妹林清瑶，与尹芝手挽着手，姐妹之间很快有说不完的话...",
[511]="尹芝低眉对着众人施了一福，随后转身，独自往山下走去。依旧是一介散修，如无根浮萍般漂泊。",
[512]="族长拜见",
[513]="小人家族中产业，常有宵小来犯，因此，小人斗胆想请求仙师下凡，于家族中显露仙法，让周围宵小莫敢冒犯！同时也能为家族扩张有所依仗",
[514]="狐假虎威，退下！",
[515]="弟子在凡人家族中显露仙法，一番震慑后，周围宵小哪里敢再为难家族。同时，家族有了依仗，也开始扩张势力范围。族长大喜过望，附上不少珍贵宝物作为谢礼",
[516]="族长恭敬退下，直到山下，族长才发现自己一身冷汗，手脚发冷，但总算平安下山，心有余悸地长舒了一口气",
[517]="家族奉礼",
[518]="在下谷氏家族族长，在此恭贺<color=#3375c0>[ZM]</color>仙师结成金丹，从此寿元大涨，更近大道一步，并奉上贺礼，望上仙笑纳",
[519]="收下贺礼",
[520]="随后有门中弟子带着族长，去到专为凡人准备的酒席位置，众人在席间觥筹交错，好不热闹",
[521]="恭贺<color=#3375c0>[ZM]</color>仙师修成金丹，从此逍遥于天地，离永生不灭更近一步，小人准备一份微薄贺礼，还望上仙不吝笑纳",
[522]="封印魔气",
[523]="流枫谷的残存魔气，虽一直被山神娘娘压制，但这并非长久之计，而我等已找到封印之法，但缺一名金丹修士一同主持阵法，因此来贵宗请求协助",
[524]="婉拒，弟子忙于修行",
[525]="在弟子帮助下，流枫谷的魔气终于被彻底封印，山神娘娘得以脱身，不需一直压制魔气，因此附上一份谢礼",
[526]="随后，洪凯与众人拱手拜别，转身下山，去找其他愿意协助封印魔气的仙友去了",
[527]="需准备片刻，仙友请稍候",
[528]="以物易物",
[529]="太岳散修游广易偶然得到一批妖丹，可惜并不懂如何炼成丹药，偏偏他感受到一丝突破契机，正急需丹药，便上门来询问<color=#ca631d>20枚二品妖丹能换多少丹药</color>？",
[530]="散修不易，慷慨相助",
[531]="童叟无欺，公平交易",
[532]="奇货可居，哄抬物价",
[533]="游广易拿到超出预想的10枚<color=#3375c0>蓝品清尘丹</color>，宗门则收到<color=#ca631d>20枚二品妖丹</color>，双方皆大欢喜，拱手拜别后，便各自散去",
[534]="游广易拿到5枚<color=#3375c0>蓝品清尘丹</color>，估计刚好够用，被他小心收好后，面带笑容与弟子们拱手道别，转身下山去了。弟子们也将<color=#ca631d>20枚二品妖丹</color>放入宗门库房中。",
[535]="游广易脸色沉闷，只换到3枚<color=#3375c0>蓝品清尘丹</color>，此次突破风险大了不少，也不与弟子们多说什么，心事重重地下山去了，弟子们也将<color=#ca631d>20枚二品妖丹</color>放入宗门库房中",
[536]="请仙友稍候片刻",
[537]="游广易回访",
[538]="散修游广易突破修为后，在秘境中寻得一批适合宗门发展用的物资，念在上次交易中，宗门的相助之情，便把物资送了过来，权当做是一份微薄谢礼，其中有<color=#ca631d>3阶妖丹*10、二阶上品灵木*3、二阶上品矿石*3</color>",
[539]="谢礼太重，理应返礼",
[540]="客套一番，收下谢礼",
[541]="散修游广易送完礼后离去，将这次交易时，宗门提供帮助之事广而告之，令周边修士对宗门的商誉纷纷表示赞赏",
[542]="获得宗门状态：<color=#549327>仙道楷模（所有弟子突破境界成功率+5%），持续12小时</color>",
[543]="散修游广易送完礼后，便下山离去。而他本人擅长狩猎妖兽、寻宝探脉，并承诺<color=#ca631d>下次得到好东西，会再次登门拜访</color>，令人不由心生期待",
[544]="散修游广易突破修为后，在秘境中寻得一批适合宗门发展用的物资，念在上次与宗门进行交易相当及时，使他把握住突破契机，从而成功突破境界，便把物资送了过来，权当做是一份微薄谢礼，其中有<color=#ca631d>3阶妖丹*5、二阶上品灵木*2、二阶上品矿石*2</color>",
[545]="俏皮少女",
[546]="一名自称伊曼的俏皮少女来访，修为相当高深，开口就要求门中安排<color=#ca631d>筑基以上，最好是元婴以上的弟子</color>，协助她探索秘境，<color=#ca631d>弟子境界越高，帮助越大，更有可能成功</color>。若此事是顺利，自然少不了好处",
[547]="答应派人",
[548]="不答应也得答应",
[549]="派去协助“伊曼前辈”的弟子返回宗门，此行相当顺利，不但得到一批物资奖励、提升了弟子修为，伊曼前辈还记下了此次相助之情",
[550]="<color=#ca631d>{dname1}修为经验提升{num1}</color>",
[551]="派去协助“伊曼”前辈的弟子返回宗门，此行并不顺利，伊曼前辈似乎还负了伤，但依然给了些物资奖励，还说会记下此次相助之情",
[552]="上前招呼",
[553]="元婴大典·壹",
[554]="宗门举办元婴大典，净缘大师上门祝贺，并提出为元婴期弟子诵读佛门心法，可助其稳住心神、巩固境界。而心法有两本且功效不同，其中<color=#3375c0>《达摩心经》对境界修为有颇大助益</color>，而<color=#c82c2c>《大明王经》可将溢散的修为融入体魄，提升体修</color>！要为<color=#ca631d>元婴弟子</color>诵读哪本？",
[555]="诵读《达摩心经》",
[556]="诵读《大明王经》",
[557]="两本全都要！",
[558]="数个时辰后，净缘大师与弟子一同走出静室，只见弟子发肤中暗藏荧光，气息内敛，神情平淡，修为明显更加巩固，甚至精进了不少！",
[559]="数个时辰后，净缘大师与弟子一同走出静室，只见弟子发肤暗藏荧光，气息内敛，神情平淡，修为明显更加巩固，甚至精进了不少！",
[560]="<color=#ca631d>{dname1}体修经验提升{num1}</color>",
[561]="<color=#ca631d>{dname1}修为经验提升{num1}\n{dname1}体修经验提升{num2}</color>",
[562]="谦逊收下",
[563]="文先生造访",
[564]="幽萤谷兽潮残留了大量煞气，大夏学宫因此派出书生文思源，深入幽萤谷中布下浩然法阵，肃清邪煞之气，以免此地发生异变。而文先生希望门中能派遣弟子，为其护法，<color=#ca631d>弟子境界越高，此事方能万无一失</color>！",
[565]="派遣弟子，协助护法",
[566]="委婉拒绝，自行前去",
[567]="幽萤谷的隐患被彻底解决，弟子带着此行的收获以及文思源的谢礼归来，并将这些物资都安放到宗门的库房之中",
[568]="虽然并未派弟子协助，文思源却毫不在意，反而提起上次搭救之恩，并取出一份储物袋，作为谢礼，并请门中收下",
[569]="收下心得，返回门中",
[570]="炼器心得",
[571]="炼器师洪铠得知门中有弟子能炼制法宝，便兴冲冲前来，表示他独自炼器走过不少弯路，希望能与炼器弟子多交流心得，<color=#ca631d>可安排精通炼器的弟子与其深入交流，也可安排略懂炼器的弟子，向洪铠讨教经验</color>",
[572]="高手探讨，深入交流",
[573]="略懂皮毛，讨教经验",
[574]="炼器10级及以上弟子",
[575]="炼器5级及以上弟子",
[576]="炼器之术繁复深奥，而洪凯与弟子都是个中好手，对自身经验直言不讳，深入探讨，还在炼器阁中锤炼各式金石，双方都收获良多，弟子更将此次心得记录在案，呈递给祖师",
[577]="炼器之术繁复深奥，洪凯却是个中好手，毫不吝啬地将自己的心得告知弟子，还在炼器阁中锤炼各式金石，令弟子收获良多，不禁对洪铠感到钦佩，弟子更将此次心得记录在案，呈递给祖师",
[578]="收下典籍，喜不自胜",
[579]="探讨此事",
[580]="白姝来信",
[581]="白姝书信一封，借付时卿之手转交西门宇，而信中竟夹带暗层，透露关押的位置，明显在<color=#ca631d>知会西门宇想办法救她脱身</color>。只是此等行径，算是利用了学宫对她的信任，令人犹豫...",
[582]="取出暗信，揭穿白姝",
[583]="派遣西门宇前去解救",
[584]="众人坦诚交出暗信，令付时卿十分钦佩，他取出数本珍藏的典籍，赠予弟子，而弟子们看那保存极好的书籍，也甚是喜爱",
[585]="白姝通过暗信，知会西门宇前去学宫解救她，未曾想她被禁足在儒圣祠堂，西门宇潜入后很快被人发现，还被狠狠揍了一顿，幸亏付时卿仙友搭救，才得以归来",
[586]="<color=#c82c2c>{dname1}被扁了一顿，负伤值+{num1}</color>",
[587]="恭送仙友",
[588]="付时卿拜贺",
[589]="天云洲盛行儒道，而一些天资出众者，并不契合儒道，而贵宗如今培养出化神修士，可见用心。因此想引荐人才给贵宗，不知意下如何？",
[590]="收下引荐令",
[591]="心领了，婉拒",
[592]="使用获得绝伦弟子",
[593]="付时卿取出引荐令，并将此次大典的贺礼一并交给弟子们。弟子们恭谦收下贺礼，并引他入席就坐，直到隆重热闹大典结束，付仙友才起身准备离开",
[594]="付时卿将提前准备的大典贺礼取出，交给弟子们。弟子们恭谦收下贺礼，并引他入席就坐，直到隆重热闹大典结束，付仙友才起身准备离开",
[595]="东湖宫秘境",
[596]="此番即将飞升去，想起在化龙雷劫时，受仙友点拨，才得以寻回冲击天劫的心气，故在水府中留有一些传承，权当报答仙友相助，其中或有阵法阻挡，但不会伤人，可派门下弟子前去历练一番，想必会有所收获，还请笑纳。",
[597]="记下秘境，感谢龙君",
[598]="必须马上立刻去龙宫！",
[599]="东湖宫之宝尽收回门中，恰在此时，九霄云巅竟凝出一道云龙，朝宗门注视，随后云龙化雨，滋润宗门灵田林地。弟子们不由想起已往仙界的龙君东湖，亦有所感，道心越发澄明！",
[600]="获得宗门状态：<color=#549327>道心澄明（弟子自行修炼效率 +10%），持续12小时</color>\n获得宗门状态：<color=#549327>云龙化雨（灵田、林场产量+20%），持续24小时</color>",
[601]="东湖宫之宝尽收回门中，恰在此时，九霄云巅竟凝出一道云龙，朝宗门注视，随后云龙化雨，滋润宗门灵田林地。弟子们想起已往仙界的龙君东湖，亦有所感，道心越发澄明！",
[602]="<color=#C55A11>{dname1}</color>在打坐时忽然感到背后一阵阴风吹来，顿时感到毛骨悚然无法入定，可是一看背后又什么都没有，此事成为其一个心魔，<color=#0070C0>渡劫成功率-{0}%</color>",
[603]="<color=#C55A11>{dname1}</color>在培植灵草时发现土里好像有什么东西，挖出了发现是一具白骨，其上附有强烈的邪气，<color=#C55A11>{dname1}</color>不慎被邪气侵蚀，<color=#0070C0>负伤值+{num1}</color>",
[604]="<color=#C55A11>{dname1}</color>在炼丹房炼制丹药时，忽然从丹炉中伸出一只焦黑的怪手，抓住<color=#C55A11>{dname1}</color>就要往里面拖，<color=#C55A11>{dname1}</color>拼死挣脱，但身体不免被灼伤，<color=#0070C0>负伤值+{num1}</color>",
[605]="<color=#C55A11>{dname1}</color>在林场培植完灵木后，却发现自己竟迷失在树林中找不到出路，且无法集中灵力御空飞行，<color=#C55A11>{dname1}</color>在林中被困了一夜，第二天方才被救出，心智大为受损，<color=#0070C0>渡劫成功率-{0}%</color>",
[606]="<color=#C55A11>{dname1}</color>在矿场中开采矿石，听到矿洞深处传来一阵哭声，正要走过去看看，头顶却有无数石头落下，将<color=#C55A11>{dname1}</color>砸伤，<color=#0070C0>负伤值+{num1}</color>",
[607]="<color=#C55A11>{dname1}</color>在经营商铺时，临近打烊来了一位奇怪的客人，<color=#C55A11>{dname1}</color>正要上前接待，忽然被其一把抓住，顿时被吸取了不少阳气倒下，清醒过来时已是第二天清晨，<color=#0070C0>境界修为-{num1}</color>",
[608]="<color=#C55A11>{dname1}</color>在炼器阁生产时，周围的兵器忽然腾空飞起，向<color=#C55A11>{dname1}</color>如骤雨般袭来，<color=#C55A11>{dname1}</color>使出浑身解数抵挡，方才逃出生天，但仍不免负伤，<color=#0070C0>负伤值+{num1}</color>",
[609]="<color=#C55A11>{dname1}</color>在锁妖塔历练时，脚下忽然出现了一双鬼手，将其抓住使其无法闪躲妖兽的攻击，不慎受到重击，<color=#0070C0>负伤值+{num1}</color>",
[610]="<color=#C55A11>{dname1}</color>闲逛到山门附近，发现有一群人在拜山，正要上前寻问，却发现这是一群厉鬼，一拥而上就要将其拖出山门，<color=#C55A11>{dname1}</color>燃烧精血使出秘法方才挣脱，事后仍心有余悸，<color=#0070C0>境界修为-{num1}</color>",
[611]="<color=#C55A11>{dname1}</color>在灵池中打捞灵石，水中忽然出现一个黑影，霎时间就要将其拖入无底深渊，<color=#C55A11>{dname1}</color>使出浑身解数方才逃脱，但仍因此留下心魔，<color=#0070C0>渡劫成功率-{0}%</color>",
[612]="<color=#ca631d>{dname1}</color>在仙界探索时，遭遇一条蛟龙，奔雷走电强如怪物，拼尽全力无法战胜，只得落得一身伤势逃离，<color=#0070C0>负伤值+{num1}</color>",
[613]="<color=#ca631d>{dname1}</color>在仙界探索时，偶然发现一处神秘仙墟，进入其中探索，不幸触碰机关，费尽周折方才逃出，<color=#0070C0>负伤值+{num1}</color>",
[614]="<color=#ca631d>{dname1}</color>在仙界探索时，忽见一件神秘法宝，正欲上前将其拾取，熟料法宝忽然爆发强大禁制，将<color=#ca631d>{dname1}</color>震伤并消失，<color=#0070C0>负伤值+{num1}</color>",
[615]="<color=#ca631d>{dname1}</color>在仙界探索时，一道金光突然闪落，正巧落在<color=#ca631d>{dname1}</color>身上，只感一股暖流涌入体内，修为有所增长，<color=#0070C0>境界修为+{num1}</color>",
[616]="<color=#ca631d>{dname1}</color>在仙界探索时，偶然发现一处神秘灵泉，泉中灵气凝如实质，<color=#ca631d>{dname1}</color>喝上一口，顿感灵气磅礴，<color=#0070C0>境界修为+{num1}</color>",
[617]="<color=#ca631d>{dname1}</color>在仙界探索时，偶遇两名仙界修士争斗，两人各显神通，法力无边，<color=#ca631d>{dname1}</color>在旁观战，亦有所感悟，<color=#0070C0>境界修为+{num1}</color>",
[618]="<color=#ca631d>{dname1}</color>在仙界探索时，碰巧发现一根通灵芝草，费尽功夫将其抓住后，熬制成一碗药汤服下，顿有七窍俱通，如有神助，<color=#0070C0>炼体修为+{num1}</color>",
[619]="<color=#ca631d>{dname1}</color>在仙界探索时，发现一块神秘石碑，上面的文字讳莫难懂，<color=#ca631d>{dname1}</color>观察良久后，石碑上的文字忽如蝌蚪般游入他的体内，顿觉身体如经淬洗，<color=#0070C0>炼体修为+{num1}</color>",
[620]="<color=#ca631d>{dname1}</color>在仙界探索时，被一群仙界妖物追杀，拼尽所能使出洪荒之力方才逃出生天，因祸得福感觉有所突破，<color=#0070C0>炼体修为+{num1}</color>，<color=#0070C0>负伤+{num2}</color>",
[621]="<color=#ca631d>{dname1}</color>在仙界探索时，不幸落入一片神秘花丛，里面的奇花异草个个化作俊男美女邀其同乐，<color=#ca631d>{dname1}</color>被其纠缠良久，方才勉强脱困，然精气不免损虚，<color=#0070C0>炼体修为-{num1}</color>，<color=#0070C0>负伤+{num2}</color>",
[622]="<color=#C55A11>{dname1}</color>误入一洞府，自觉在其中闭关数十年，出来才发现外界才过了短短一炷香时间，想要回头再进入洞府，却已找不到来路，<color=#0070C0>境界修为+{num1}</color>",
[623]="<color=#C55A11>{dname1}</color>在外游历过程中偶遇一名乞丐，大发善心给予帮助。不料此人竟是一名绝世高人，一时落难，被其所救。多年以后，前来报答，以{item1}相赠，以报当日之恩",
[624]="<color=#C55A11>{dname1}</color>游历途中忽见一块天外陨石正在落下，急忙赶去查看。成功在陨石中提炼出一块{item1}，同时炼器技能也有所精进，<color=#0070C0>炼器经验+{num1}</color>",
[625]="<color=#C55A11>{dname1}</color>造访了一处家族，与其家族长老座而论道，受益匪浅，<color=#0070C0>境界修为+{num1}</color>",
[626]="<color=#C55A11>{dname1}</color>在御气飞行时竟然意外坠落山林，被当地的凡人视为天神下凡，好吃好喝的供奉了起来，<color=#C55A11>{dname1}</color>干脆也就地闭关数年，<color=#0070C0>境界修为+{num1}</color>",
[627]="<color=#C55A11>{dname1}</color>在游历途中发现了一部炼体偏方，自行收拢材料尝试，效果斐然，<color=#0070C0>炼体修为+{num1}</color>",
[628]="<color=#C55A11>{dname1}</color>在外游历偶遇一只受伤的白鹤，出于好心为其疗伤。白鹤伤愈飞走，不久之后竟叼回来一颗{item1}。万物有灵，白鹤报恩。",
[629]="<color=#C55A11>{dname1}</color>在外游历过程中偶然得到一件金丝缕衣，惊讶地发现雷电竟然会从金丝缕衣上流过，而不伤及穿戴者。原来此衣乃上古修士留下的法宝，名曰“绝缘服”，专为渡劫所制，只是使用一次之后即会损毁，<color=#0070C0>境界渡劫成功率+{num1}%</color>",
[630]="<color=#C55A11>{dname1}</color>在外游历途中发现一座古墓，进入古墓中探索，成功找到了几册{item1}，看来墓主曾经也是修炼之人。",
[631]="<color=#C55A11>{dname1}</color>游历途中灵光一闪，冥冥中感到自己即将悟道，赶紧打坐修行，一番静心冥想后，终于悟出一招空手道，虽然并无大用，但也能强身健体，<color=#0070C0>炼体经验+{num1}</color>",
[632]="<color=#C55A11>{dname1}</color>在外游历途中偶得一株变异灵草，带回宗门药园中培植，与本地灵草杂交成功。虽无特殊功效，但颜色更加好看了。<color=#0070C0>培植经验+{num1}</color>",
[633]="<color=#C55A11>{dname1}</color>在外游历过程中遇到一群山贼作乱，决定出手教训。本想抓个小贼，没想到捅了老窝，顺势将附近的贼人营寨一网打尽，任何邪恶终将绳之以法",
[634]="<color=#C55A11>{dname1}</color>在游历途中与一位散修意外结仇，恐怕下次见面二者就要大打出手了",
[635]="<color=#C55A11>{dname1}</color>在游历途中冥冥感到了自己突破的机遇所在，一阵忙活后却发现浪费了数年光阴",
[636]="<color=#C55A11>{dname1}</color>在游历途中发现了一本秘籍，尝试修行发现自身的修为增长了些许，<color=#0070C0>境界修为+{num1}</color>",
[637]="<color=#C55A11>{dname1}</color>在游历途中发现了一部炼体偏方，自行收拢材料尝试，但却没什么成效，看来这偏方并非真品",
[638]="<color=#C55A11>{dname1}</color>偶然发现了一处正在被邪修破坏的凡人村庄，路见不平，拔剑相助，那邪修不敌<color=#C55A11>{dname1}</color>，负伤逃窜，落下些许财物，让<color=#C55A11>{dname1}</color>捡到了{item1}",
[639]="<color=#C55A11>{dname1}</color>闭关修炼数月，出关寻找作恶妖兽试验自身闭关成果，收集了些许妖兽材料，获得了{item1}",
[640]="<color=#C55A11>{dname1}</color>在一山崖下发现了一处花丛，堪称人间美景，遂在此地定居数年，期间还发现了少许稀有花草，带回了{item1}",
[641]="<color=#C55A11>{dname1}</color>自觉修为难以突破，外出体验人生百态，偶得良机开始经商，沉迷赚钱，无心修行，回过神来时已经荒废了许多时日，<color=#0070C0>境界修为-{num1}</color>，<color=#0070C0>商道经验+{num2}</color>",
[642]="<color=#C55A11>{dname1}</color>游历途中误入一处仙门阵法，在阵中被困许久，无法离开。后以蛮力强行突破，身负重任。但也因祸得福，对阵法有更深的了解，<color=#0070C0>负伤值+{num1}</color>，<color=#0070C0>阵法经验+{num2}</color>",
[643]="<color=#C55A11>{dname1}</color>路遇 一名散修，两人先是友好切磋，后演变成大打出手，彼此倒地不起后又开始惺惺相惜。正所谓不打不相识，此战过后两人的修为都有所提升，<color=#0070C0>负伤值+{num1}</color>，<color=#0070C0>境界修为+{num2}</color>",
[644]="<color=#C55A11>{dname1}</color>游历途中，不慎被一神秘宗门劫走，充当外门弟子打杂。多年以后，终于成功逃出，虽然修为荒废不少，但也更加精通外门杂事，<color=#0070C0>境界修为-{num1}</color>，<color=#0070C0>培植技能+{num2}</color>，",
[645]="<color=#C55A11>{dname1}</color>在游历途中发现了一本秘籍，尝试修行之后发现并没有什么作用",
[646]="<color=#C55A11>{dname1}</color>在某地仙市中发现了一种自己想要的材料，但却苦于手头缺少灵石，又没有珍惜物件用于交换，鬼迷心窍下试图盗取此物，被物主发现后痛打一顿，仓皇逃窜，<color=#0070C0>负伤值+{num1}</color>",
[647]="<color=#C55A11>{dname1}</color>在游历途中发现了一本秘籍，尝试修行却发现法力相冲，险些走火入魔，<color=#0070C0>境界修为-{num1}</color>",
[648]="<color=#C55A11>{dname1}</color>路遇黑市，买到一颗神秘丹药，服用后腹痛难当，修为不进反退。真是假药害人，服用须谨慎。<color=#0070C0>境界修为-{num1}</color>",
[649]="<color=#C55A11>{dname1}</color>游历途中忽见一块天外陨石正在落下，急忙赶去查看。结果操之过急，不幸被陨石砸中，顿时失去意识。苏醒过来时，天外陨石已不知所踪，<color=#0070C0>负伤值+{num1}</color>",
[650]="<color=#C55A11>{dname1}</color>在外游历途中发现一座古墓，进入古墓中探索，意外惊动守墓机关，只能狼狈逃出。<color=#0070C0>负伤值+{num1}</color>",
[651]="<color=#C55A11>{dname1}</color>在外游历，偶遇一名江湖术士，称其有血光之灾。<color=#C55A11>{dname1}</color>不以为意，转身离去，果然第二天起床脚趾不慎撞到石头，一时疼痛难当。伤害不大，侮辱极强，<color=#0070C0>负伤值+{num1}</color>",
[652]="<color=#C55A11>{dname1}</color>游历途中，被一名江湖术士所骗，买到一本地摊功法，修炼途中险些走火入魔，<color=#0070C0>境界修为-{num1}</color>",
[653]="<color=#C55A11>{dname1}</color>在山中修炼时常与附近猴儿玩闹嬉戏，在他即将离开山林时，猴儿竟奉上些许酒水，饮用后增长了<color=#0070C0>{num1}</color>点境界修为，<color=#C55A11>{dname1}</color>心念同门，决定将剩下的{item1}打包带走",
[654]="<color=#C55A11>{dname1}</color>在太岳山脉偶遇他宗修士，二人相谈甚欢，一同游历数月，临别得到了些许赠礼，<color=#0070C0>{item1}+1</color>",
[655]="<color=#C55A11>{dname1}</color>在太岳山脉发现一处小型洞府，其中尚有些许精纯灵气，<color=#C55A11>{dname1}</color>在此修炼数月，<color=#0070C0>境界修为+{num1}</color>",
[656]="<color=#C55A11>{dname1}</color>在太岳山脉发现一处小型洞府，其中有数份{item1}散落，看来洞府先前的主人走得匆忙",
[657]="<color=#C55A11>{dname1}</color>在太岳山脉与一只修炼有成的妖兽大战数日，未能分出胜负",
[658]="<color=#C55A11>{dname1}</color>在太岳山脉巧遇他宗弟子，与其进行了友好切磋，<color=#0070C0>功法经验+{num1}</color>",
[659]="<color=#C55A11>{dname1}</color>在太岳山脉的一处洞窟之中捡到了{item1}",
[660]="<color=#C55A11>{dname1}</color>在太岳山脉与一只小猴一同嬉戏玩闹，临别时小猴竟奉上{item1}一份",
[661]="<color=#C55A11>{dname1}</color>在太岳山脉与一只修炼有成的妖兽大战数日，虽未能分出胜负，但依然受益匪浅，<color=#0070C0>功法经验+{num1}</color>",
[662]="<color=#C55A11>{dname1}</color>在太岳山脉偶遇高人指点，功法突飞猛进，<color=#0070C0>功法经验+{num1}</color>",
[663]="<color=#C55A11>{dname1}</color>登上了太岳山脉的最高处，登高瞭望天地，不觉间修为有了些长进，<color=#0070C0>境界修为+{num1}</color>",
[664]="<color=#C55A11>{dname1}</color>在太岳山脉一处山崖底下发现一本{item1}，不知何人藏在此处，等待坠崖的人发现。",
[665]="<color=#C55A11>{dname1}</color>在太岳山脉挖掘到一块奇石，其形状独特怪异，一看就是不凡的炼器材料<color=#0070C0>{item1}+1</color>",
[666]="<color=#C55A11>{dname1}</color>在太岳山脉偶然发现一处世外桃源，在此闭关修炼数月，修为大有长进。<color=#0070C0>境界修为+{num1}</color>",
[667]="<color=#C55A11>{dname1}</color>在太岳山脉被一颗落下的果实砸中脑袋，正要发作之际，才发现这是一颗<color=#0070C0>{item1}+1</color>，顿时转怒为喜，感谢大自然的馈赠",
[668]="<color=#C55A11>{dname1}</color>在太岳山脉被一颗落下的果实砸中脑袋，忽然心中有所感悟——果实还是落地成熟的好吃，<color=#0070C0>培植经验+{num1}</color>",
[669]="<color=#C55A11>{dname1}</color>在太岳山脉与一位负伤邪修偶遇，双方互有忌惮，最终擦肩而过，并未爆发战斗",
[670]="<color=#C55A11>{dname1}</color>在太岳山脉遭遇了一只神通不凡的妖兽，与之相斗却落败负伤，<color=#0070C0>负伤值+{num1}</color>",
[671]="<color=#C55A11>{dname1}</color>在太岳山脉独自修行时，竟被一魔修偷袭，幸好<color=#C55A11>{dname1}</color>逃得一命，但也身负重伤，不得不回宗门养伤了，<color=#0070C0>负伤值+{num1}</color>",
[672]="<color=#C55A11>{dname1}</color>在天云洲巧遇他宗弟子，与其进行了友好切磋，<color=#0070C0>功法经验+{num1}</color>",
[673]="<color=#C55A11>{dname1}</color>在天云洲的海边捡到了{item1}",
[674]="<color=#C55A11>{dname1}</color>在天云洲与一只小猴一同嬉戏玩闹，临别时小猴竟奉上{item1}一份",
[675]="<color=#C55A11>{dname1}</color>在天云洲与一位负伤邪修偶遇，双方互有忌惮，最终擦肩而过，并未爆发战斗",
