[677]="<color=#C55A11>{dname1}</color>在天云洲巧遇龙吸水的天地奇景，心中忽有所悟，修为有所提升。<color=#0070C0>境界修为+{num1}</color>",
[678]="<color=#C55A11>{dname1}</color>在天云洲游历途中偶见商贾云集，热烈非凡，前去观摩，经商水平有所提升。<color=#0070C0>商道经验+{num1}</color>",
[679]="<color=#C55A11>{dname1}</color>在天云洲参加了一场盛大的灯会，在灯会上解开数道灯谜，成功夺得头筹，获得奖品{item1}",
[680]="<color=#C55A11>{dname1}</color>在天云洲得到了一张古法符箓，尝试临摹成功，画符能力有所提升。<color=#0070C0>符箓经验+{num1}</color>",
[681]="<color=#C55A11>{dname1}</color>在天云洲发现了一处水下遗迹，进去其中探索，发现了一些先人留下的宝物，获得了{item1}",
[682]="<color=#C55A11>{dname1}</color>在天云洲偶遇高人指点，功法突飞猛进，<color=#0070C0>功法经验+{num1}</color>",
[683]="<color=#C55A11>{dname1}</color>在天云洲通天江上荡舟而行，感到心旷神怡，不觉间修为增长了少许，<color=#0070C0>境界修为+{num1}</color>",
[684]="<color=#C55A11>{dname1}</color>在天云洲偶遇他宗修士，二人相谈甚欢，一同游历数月，临别得到了些许赠礼，<color=#0070C0>{item1}+1</color>",
[685]="<color=#C55A11>{dname1}</color>在天云洲发现一处小型洞府，其中尚有些许精纯灵气，<color=#C55A11>{dname1}</color>在此修炼数月，<color=#0070C0>境界修为+{num1}</color>",
[686]="<color=#C55A11>{dname1}</color>在天云洲发现一处小型洞府，其中有一件{item1}散落，看来洞府先前的主人走得匆忙",
[687]="<color=#C55A11>{dname1}</color>在天云洲与一只修炼有成的妖兽大战数日，未能分出胜负",
[688]="<color=#C55A11>{dname1}</color>在天云洲遭遇了一只神通不凡的妖兽，与之相斗却落败负伤，<color=#0070C0>负伤值+{num1}</color>",
[689]="<color=#C55A11>{dname1}</color>在天云洲独自修行时，竟被一魔修偷袭，幸好<color=#C55A11>{dname1}</color>逃得一命，但也身负重伤，不得不回宗门养伤了，<color=#0070C0>负伤值+{num1}</color>",
[690]="<color=#C55A11>{dname1}</color>在南疆遇到了一群密修，在其邀请下参与了一场神秘祭祀。进行祭祀后，果然感觉修为有所提升。<color=#0070C0>境界修为+{num1}</color>",
[691]="<color=#C55A11>{dname1}</color>在南疆遇到了一群孔哥信徒，在他们的邀请下一起锻炼修行，经过一番苦练之后，体魄有所提升。<color=#0070C0>炼体经验+{num1}</color>",
[692]="<color=#C55A11>{dname1}</color>在南疆遇到了一名蛊巫，受其指点养蛊之术。<color=#C55A11>{dname1}</color>虽未能领悟蛊术，但对其饲养之法有所感悟。<color=#0070C0>饲养经验+{num1}</color>",
[693]="<color=#C55A11>{dname1}</color>在南疆被一部落邀请参加宴会，在宴席上吃了许多奇怪蘑菇和怪异毒虫，回来只感丹田热气上涌，一番炼化后竟觉体质有所提升。<color=#0070C0>炼体经验+{num1}</color>",
[694]="<color=#C55A11>{dname1}</color>在南疆意外被一只变异蜘蛛咬了一口，不料非但没有中毒，反而因祸得福，体魄有所提升，<color=#0070C0>炼体经验+{num1}</color>",
[695]="<color=#C55A11>{dname1}</color>在南疆沼泽中意外发现一具白骨，调查发现白骨身上有一件{item1}，看来是某个倒霉的修行者不幸葬身于此。",
[696]="<color=#C55A11>{dname1}</color>从一名南疆密修手里获得一神秘药方，自行准备材料后炼制，果然发现有滋补提神之效，<color=#0070C0>丹道经验+{num1}</color>",
[697]="<color=#C55A11>{dname1}</color>在南疆遇到了一群密修，在其邀请下参与了一场神秘祭祀。结果差点被当成祭品，几经波折方才成功逃出，身体难免负伤<color=#0070C0>负伤值+{num1}</color>",
[698]="<color=#C55A11>{dname1}</color>在南疆遇到了一群孔哥信徒，在他们的邀请下一起锻炼修行，结果被操练得半死，身心俱疲，<color=#0070C0>负伤值+{num1}</color>",
[699]="<color=#C55A11>{dname1}</color>在南疆被一部落邀请参加宴会，在宴席上吃了许多奇怪蘑菇和怪异毒虫，回来之后只感天旋地转，倒头昏睡不醒，良久之后方才醒来，只感身体虚弱，体力不支，<color=#0070C0>炼体经验-{num1}</color>",
[700]="<color=#C55A11>{dname1}</color>从一名南疆密修手里获得一神秘药方，自行准备材料后炼制后，发现并没有什么作用，白白浪费了一炉材料，也荒废了些许修为，<color=#0070C0>境界修为-{num1}</color>",
[701]="<color=#C55A11>{dname1}</color>在南疆被一名蛊巫谋害，身体被下了蛊，费了好一番功夫才将蛊虫从体内取出，但修为在此过程中有所损伤。<color=#0070C0>境界修为-{num1}</color>",
[702]="<color=#C55A11>{dname1}</color>在南疆沼泽深处忽然感受到了一股来自外域的气息，顿时被吓得道心不稳，仓皇逃窜。<color=#0070C0>境界渡劫成功率-{num1}%</color>",
[703]="<color=#C55A11>{dname1}</color>在天山游历时偶然发现了一处被雪遮蔽的洞府，原来是一处上古修士静修之地，从中获得了<color=#0070C0>{item1}</color>",
[704]="<color=#C55A11>{dname1}</color>在天山与一位魔修偶遇，爆发了一场大战，<color=#C55A11>{dname1}</color>侥幸取胜，生死关头，有所感悟，<color=#0070C0>功法经验+{num1}</color>",
[705]="<color=#C55A11>{dname1}</color>在一处极寒冰湖中锻炼自身体魄，数年不止，终有所得。<color=#0070C0>炼体经验+{num1}</color>",
[706]="<color=#C55A11>{dname1}</color>在天山巧遇他宗弟子，与其进行了友好切磋，双方点到为止，交流心得，<color=#0070C0>功法经验+{num1}</color>",
[707]="<color=#C55A11>{dname1}</color>在天山登高而望，只见天地间一片苍茫，忽然有所感悟，<color=#0070C0>境界修为+{num1}</color>",
[708]="<color=#C55A11>{dname1}</color>寻了一处雪峰山顶御剑疾驰而下，不慎引发了雪崩，所幸周围并无人烟",
[709]="<color=#C55A11>{dname1}</color>在天山与一只修炼有成的苍狼大战数日，未能分出胜负，彼此惺惺相惜，决定就此停手",
[710]="<color=#C55A11>{dname1}</color>在天山游历时不幸跌落冰湖，被湖中异兽袭击，无奈化四周湖水为坚冰保护自身，直至被偶然路过的好心修士救出，<color=#0070C0>负伤值+{num1}</color>",
[711]="<color=#C55A11>{dname1}</color>在天山游历时撞见魔修杀人祭刀，与之大战数百回合却仍不是对手，无奈败退，<color=#0070C0>负伤值+{num1}</color>",
[712]="<color=#C55A11>{dname1}</color>在天山遭遇了一只修为不凡的妖兽，与之相斗却不幸遗憾告败，<color=#0070C0>负伤值+{num1}</color>",
[713]="【道侣】<color=#ca631d>{dname1}</color>静修数年，出关时一眼望见<color=#ca631d>{dname2}</color>，想来她已等候许久，二人难掩喜悦，佳人如云雀般扑入<color=#ca631d>{dname1}</color>怀中，二人好感上升",
[714]="【道侣】<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>相伴云游，正是落花时节好风景，二人携手踏青崖，随风银铃笑，挽花簪云鬓，惹得娇人羞，二人好感上升",
[715]="【道侣】<color=#ca631d>{dname1}</color>正在研习功法，<color=#ca631d>{dname2}</color>来到身前，二人相视片刻，<color=#ca631d>{dname1}</color>轻咳起身想溜，<color=#ca631d>{dname2}</color>一把拉住他说道：走！跟我进屋！",
[716]="【道侣】<color=#ca631d>{dname1}</color>为宗门事务劳累数日，归来时，道侣<color=#ca631d>{dname2}</color>已备好热水净衣，还有美味吃食，为其解乏放松，<color=#ca631d>{dname1}</color>倍感温馨，二人好感上升",
[717]="【道侣】<color=#ca631d>{dname1}</color>修为有所停滞，与道侣<color=#ca631d>{dname2}</color>倾述，<color=#ca631d>{dname2}</color>为其查阅典籍、询问师友，<color=#ca631d>{dname1}</color>却恼其四处宣扬，二人各持己见，斗气数日，二人好感下降",
[718]="【道侣】<color=#ca631d>{dname1}</color>下山归来，将精心备好礼物带给道侣<color=#ca631d>{dname2}</color>，<color=#ca631d>{dname2}</color>开心收下，<color=#ca631d>{dname1}</color>开始说起下山的一桩桩趣事，二人好感上升",
[719]="【道侣】<color=#ca631d>{dname1}</color>为处理宗门事务，与同门师妹外出一趟，其道侣<color=#ca631d>{dname2}</color>得知后，却心怀揣测，对归来的<color=#ca631d>{dname1}</color>冷言冷语，令其颇为心伤，二人好感有所下降",
[720]="【道侣】<color=#ca631d>{dname2}</color>游历受伤，<color=#ca631d>{dname1}</color>取出珍品灵药为其治疗，<color=#ca631d>{dname2}</color>有些感动，但还是说自己想静静，将其推出房外，<color=#ca631d>{dname2}</color>好感有所上升",
[721]="【道侣】<color=#ca631d>{dname1}</color>对道侣<color=#ca631d>{dname2}</color>全心信任，将俸禄交由其看管，可平日修行需灵石用度时，<color=#ca631d>{dname2}</color>却百般不愿，千般克扣，令其困扰不已，对其好感下降",
