[783]="【道侣】师尊之命不可违，<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>最终和离，<color=#ca631d>{dname1}</color>从此萎靡不振，修为下降，获得特质<color=#ca631d>“黯然神伤”</color>，<color=#ca631d>{dname2}</color>获得特质<color=#ca631d>“念念不忘”</color>",
