[785]="【道侣】师尊之命不可违，<color=#ca631d>{dname2}</color>忍痛与<color=#ca631d>{dname1}</color>和离，<color=#ca631d>{dname2}</color>从此萎靡不振，久久无法释怀，修为下降，获得特质<color=#ca631d>“黯然神伤”</color>",
[786]="【道侣】<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>听从师命和离，却时常想起二人和美的日子，不能专心修行，修为下降，<color=#ca631d>{dname1}</color>获得特质<color=#ca631d>“念念不忘”</color>，<color=#ca631d>{dname2}</color>获得特质<color=#ca631d>“黯然神伤”</color>",
[787]="【道侣】<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>听从师命和离，<color=#ca631d>{dname1}</color>却时常想起二人和美的日子，不能专心修行，修为下降，获得特质<color=#ca631d>“念念不忘”</color>",
[788]="【道侣】<color=#ca631d>{dname1}</color>听从师命，与<color=#ca631d>{dname2}</color>和离，<color=#ca631d>{dname1}</color>却时常想起二人和美的日子，不能专心修行，修为下降，获得特质<color=#ca631d>“念念不忘”</color>",
[789]="【道侣】<color=#ca631d>{dname2}</color>听从师命，与<color=#ca631d>{dname1}</color>和离，<color=#ca631d>{dname2}</color>却时常想起二人和美的日子，不能专心修行，修为下降，获得特质<color=#ca631d>“念念不忘”</color>",
[790]="【道侣】师尊之命不可违，<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>最终和离，<color=#ca631d>{dname2}</color>从此萎靡不振，修为下降，获得特质<color=#ca631d>“黯然神伤”</color>",
[791]="【道侣】<color=#ca631d>{dname1}</color>与<color=#ca631d>{dname2}</color>听从师命和离，<color=#ca631d>{dname2}</color>却时常想起二人和美的日子，不能专心修行，修为下降，获得特质<color=#ca631d>“念念不忘”</color>",
[792]="<color=#C55A11>{dname1}</color>忙里偷闲、在宗门周围闲逛时偶然发现了{item1}，放入了自己的储物袋中",
[793]="<color=#C55A11>{dname1}</color>感觉自己即将尝试突破到下一个境界，得到了同门弟子的祝福和赠礼，<color=#C55A11>{dname1}</color>虽将赠礼一一谢绝，但其中{item1}实在得其欢心，忍不住厚颜将其收下，放入储物袋中",
[794]="<color=#C55A11>{dname1}</color>在宗门与好友一同聊天时，突然有一只妖兽闯入，<color=#C55A11>{dname1}</color>挺身而出，与之交战，很快将妖兽击败，并从其身上取得{item1}，作为战利品收入储物袋中",
[795]="在斗法台观战时，突然一道流光从战场飞入<color=#C55A11>{dname1}</color>的怀中，居然是一个储物袋。<color=#C55A11>{dname1}</color>拾金不昧，在之后物归原主，得到失主万分感谢，特赠{item1}作为谢礼",
[796]="<color=#C55A11>{dname1}</color>孤身一人前往锁妖塔挑战自我，数个时辰后满足地回到了自己的洞府，宗门长老赞赏其勇气，给予他{item1}作为奖励",
[797]="获得俸禄之后，<color=#C55A11>{dname1}</color>前往宗门内的商铺，买下了自己心仪已久的{item1}，放入储物袋中",
[798]="<color=#C55A11>{dname1}</color>从游历归来的同门处获得了对方带回的信件、其中放有{item1}，是宗外结识的好友给他寄来的礼物",
[799]="<color=#C55A11>{dname1}</color>和天狗相谈甚欢，天狗开心的在小窝附近刨出了一件{item1}赠送给了<color=#C55A11>{dname1}</color>",
[800]="<color=#C55A11>{dname1}</color>最近频频造访藏经阁，刻苦学习功法典籍，传功长老很是欣慰，将其作为榜样、当众赠与{item1}，望其再接再厉",
[801]="<color=#C55A11>{dname1}</color>在庶务殿与同门友人告别，在临别时获赠{item1}作为纪念",
[802]="<color=#C55A11>{dname1}</color>在坊市买了个盒子，却意外发现其底部还有暗格，打开后从暗格中得到了{item1}，真是意外之喜",
[803]="<color=#C55A11>{dname1}</color>在宗门附近练习御空飞行战斗时意外丢失了自己的储物袋，好不容易寻回、却发现其中丢失了{item1}，甚是痛心",
[804]="<color=#C55A11>{dname1}</color>在境界堪堪圆满、准备尚且不足时，贸然尝试突破境界，结果在雷劫中遗失了储物袋，找回时里面已经丢失了{item1}",
[805]="<color=#C55A11>{dname1}</color>在宗门周围想要扫荡些妖兽，没想到打了小的来了老的，匆忙逃离时遗失了储物袋中的{item1}",
[806]="<color=#C55A11>{dname1}</color>在斗法台战斗时意外丢失了自己的储物袋，本以为已经无法找回，却被好心人捡到归还，于是<color=#C55A11>{dname1}</color>将自己储物袋中的{item1}作为谢礼赠送给了对方",
[807]="<color=#C55A11>{dname1}</color>孤身一人前往锁妖塔锻炼自己，数个时辰后精疲力尽地离开，回到洞府倒头就睡，第二天发现自己在战斗中丢失了储物袋中的{item1}，已无法寻回",
[808]="<color=#C55A11>{dname1}</color>因为购买自己心仪的物品，手头已无灵石、举例发俸禄的日子还有数月，无奈只好卖出了自己储物袋中的{item1}，拿些灵石来周转",
[809]="<color=#C55A11>{dname1}</color>委托正打算出发游历的同门师兄弟、希望能够将其储物袋中的{item1}带给亲族朋友",
[810]="<color=#C55A11>{dname1}</color>和同门好友一同嘲笑天狗境界低微、被天狗找来它要好的师兄教训了一顿，拿{item1}作为赔礼送给了天狗",
[811]="<color=#C55A11>{dname1}</color>在藏经阁研读经典时，失手将古书弄破，只得卖了手头的{item1}，用灵石请人修复古书",
[812]="<color=#C55A11>{dname1}</color>在庶务殿与同门友人告别、将储物袋中的{item1}作为临别赠礼给予了对方",
[813]="<color=#C55A11>{dname1}</color>在黑市里与蒙面人进行了物物交易，用自己储物袋中的{item1}换到了{item2}",
[814]="<color=#C55A11>{dname1}</color>最近对于自己的境界提升速度很是不满、偷偷联系了正在炼丹阁负责炼丹的同门弟子，用自己的{item1}交换了些许{item2}，希望能早日突破境界",
[815]="<color=#C55A11>{dname1}</color>与即将远行游历的同门友人告别、用自己的{item1}与友人的{item2}进行交换，以此留念",
[816]="<color=#C55A11>{dname1}</color>在商铺买{item2}时发现自己兜中已无灵石、只得用自己储物袋中的{item1}与老板以物换物",
[817]="<color=#C55A11>{dname1}</color>将自己储物袋中的{item1}赠与了友人，得到了{item2}作为回礼",
[818]="<color=#C55A11>{dname1}</color>收集了多册{item1}，偶然间发现了其中的两册出于一处，与好友一同前往历险，成功寻得宝物{item2}",
[819]="<color=#C55A11>{dname1}</color>将自己储物袋中的{item1}安葬于宗门山下的树林中时竟发现遗体仍有残魂，得以入土为安、残魂非常感激，以自己毕生修炼心得相授。<color=#C55A11>{dname1}</color>返回宗门后，将其心得记录下来，是为{item2}",
[820]="<color=#C55A11>{dname1}</color>用储物袋中的{item1}作为材料，烹调一番，请同期的同门好友吃了个痛快",
[821]="<color=#C55A11>{dname1}</color>在黑市摆摊时，有人希望以丹药交换其手中的{item1}，此物留在<color=#C55A11>{dname1}</color>手中也不过无用装饰，便用此物交换了些许{item2}",
[822]="<color=#C55A11>{dname1}</color>在打理灵田时，偶然发现田中竟生长着一株{item1}，差点被当成杂草除掉，赶紧将其摘下来放入储物袋",
[823]="<color=#C55A11>{dname1}</color>在外游历途中，忍不住嘴馋买了一块{item1}，放入储物袋中准备带回宗门享用",
[824]="<color=#C55A11>{dname1}</color>与远道而来的好友相约对酌，两人喝得兴起，不醉不休，第二天惺惺相别，好友留下一坛{item1}，<color=#C55A11>{dname1}</color>将其收入储物袋中，留作纪念",
[825]="<color=#C55A11>{dname1}</color>在宗门附近发现了一只受伤的灵兽，好心为其治疗。第二天门前就多了一件{item1}，似乎是灵兽报恩的礼物，于是便将其收入储物袋",
[826]="<color=#C55A11>{dname1}</color>在山门处发现前来拜山之人遗留的物品，捡起来一看才发现是{item1}，由于无法得知失主是谁，只好将其收入储物袋",
[827]="<color=#C55A11>{dname1}</color>在矿场下工作时，偶然发现石壁中有什么在发光，开凿出来后发现原来是一枚{item1}，便将其收入储物袋",
[828]="<color=#C55A11>{dname1}</color>在清理灵池时，发现池内有一块奇特的玉石，拿起来之后才发现是一颗{item1}，欣然将其收入储物袋",
[829]="<color=#C55A11>{dname1}</color>在林场中歇息，偶然发现林中竟长着一株{item1}，<color=#C55A11>{dname1}</color>对此爱不释手，于是便摘下收入储物袋中",
[830]="<color=#C55A11>{dname1}</color>在仙栈中接待来客，尽心尽责，讨得客人十分欢心，将{item1}打赏给他。<color=#C55A11>{dname1}</color>欣然接受，将其收入储物袋",
[831]="<color=#C55A11>{dname1}</color>在后山中偶然遇到一只妖兽，与其大战五百回合后终于获胜，虽然难免负伤，但也从妖兽身上获得{item1}，将其收入储物袋，<color=#0070C0>负伤值+{num1}</color>",
[832]="<color=#C55A11>{dname1}</color>与其他门派的弟子切磋比试，一时兴起要求押上赌注作为彩头，最终成功战胜对方，从对方手中赢得{item1}，十分得意",
[833]="<color=#C55A11>{dname1}</color>在宗门附近发现一群鬼鬼祟祟的魔修，意欲图谋不轨，连忙挺身而出将其驱赶，慌乱间魔修掉下一件{item1}，被<color=#C55A11>{dname1}</color>作为战利品捡回，收入储物袋中",
[834]="<color=#C55A11>{dname1}</color>在宗门散步时，忽然被天空中一件东西掉下来砸到脑袋，捡起来一看原来是{item1}，不久之后猫货郎前来赔罪，原来这东西是从它的小船上掉下来的，为表歉意也就送给<color=#C55A11>{dname1}</color>用来赔罪",
[835]="<color=#C55A11>{dname1}</color>在路过酒肆时闻到一股浓郁的酒香，一时间酒瘾难耐，可苦于手头没有足够的灵石，只好用{item1}向老板换了一坛美酒，总算是能痛饮一番",
[836]="<color=#C55A11>{dname1}</color>在仙栈接待客人时，将储物袋遗留在前台，等他回来时发现已经遗失了{item1}，不禁捶胸顿足，恨自己太不小心",
[837]="<color=#C55A11>{dname1}</color>在炼器阁炼制时，储物袋中的{item1}不慎掉入火中，一时抢救不及，{item1}被烧成灰烬，使其懊恼不已",
[838]="<color=#C55A11>{dname1}</color>在逛黑市时，忽然被一名黑衣人撞到，当时还不以为意，后面才发现储物袋中的{item1}不知所终，急忙去追时，对方已不见踪影，追悔莫及",
[839]="<color=#C55A11>{dname1}</color>在经营商铺时，不慎失手打碎一堆商品，手中没有足够的灵石，只能变卖{item1}赔偿损失",
[840]="<color=#C55A11>{dname1}</color>在后山打坐静修，一时过于投入，没有注意一只猴子悄悄靠近抢走了储物袋，回过神来急忙去追赶，拿回储物袋时已丢失了{item1}，损失不大，侮辱性极强",
[841]="<color=#C55A11>{dname1}</color>与其他门派的弟子切磋比试，一时兴起押上{item1}作为赌注，一番较量后遗憾落败，只能愿赌服输，把{item1}送给对方",
[842]="<color=#C55A11>{dname1}</color>在百花坊游览时，不慎碰倒了一株名贵花卉，然后还不小心踩了一脚。苦于囊中羞涩，只能变卖了{item1}，换取灵石用以赔偿",
[843]="<color=#C55A11>{dname1}</color>在后山中偶然遇到一只妖兽，一番交手下感觉力不能敌，落荒而逃，慌乱中遗失了{item1}，再也找不回来了",
[844]="<color=#C55A11>{dname1}</color>在路过灵池时，储物袋中的{item1}不慎落入灵池中，想要打捞时却怎么也打捞不回来，仿佛溶解在了灵池之中",
[845]="<color=#C55A11>{dname1}</color>在斗法台观战时，与其他门派的弟子起了口角，差点忍不住要动手，幸好宗门长老出面调停，方才解决了这场纷争。最后<color=#C55A11>{dname1}</color>从储物袋中拿出{item1}作为赔礼，对方也拿出{item2}赔谢，双方终于冰释前嫌",
[846]="<color=#C55A11>{dname1}</color>得知远方亲朋去世，感受十分悲伤，于是修成一封仙书，放入{item1}寄出，以表怀念之情",
[847]="<color=#C55A11>{dname1}</color>听闻宗门中有一颗奇树，把东西埋进树下，第二天就能挖出双倍的数量。于是便兴冲冲地将{item1}埋进树下，第二天想来挖时，{item1}却已不知所踪，顿时疾呼上当，可为时已晚",
[848]="天狗自称自己的鼻子灵敏无比，可以闻到千里外的气味，丢了什么东西可以找回来。<color=#C55A11>{dname1}</color>不信，把自己的储物袋丢下山崖，让天狗尝试根据气味找回来。后来果真找不回来，气氛一时尴尬起来",
[849]="<color=#C55A11>{dname1}</color>在宗门附近偶遇猪妖行商，在其一番花言巧语下，决定拿{item1}换取其手中的{item2}，到底谁亏谁赚，可能都不好说",
[850]="<color=#C55A11>{dname1}</color>与同门弟子交流炼丹心得，两人一番交流之后，决定交换彼此手中的丹药留作纪念，<color=#C55A11>{dname1}</color>拿{item1}换了一颗{item2}，看看谁的丹药更好",
[851]="<color=#C55A11>{dname1}</color>想要炼制一把趁手的兵器，可是苦于手中没有合适材料，只好拜托炼器阁的同门，以{item1}换取{item2}，希望能用这些材料炼出一把合适的武器",
[852]="<color=#C55A11>{dname1}</color>热衷于收集各种有趣的小玩意，一日看到同门弟子手中有一件好玩的东西，当即决定以{item1}交换{item2}，尽管在同门看来匪夷所思，但<color=#C55A11>{dname1}</color>却乐在其中",
[853]="<color=#C55A11>{dname1}</color>在仙栈中与一名访客结为好友，临别时以{item1}相赠，得到{item2}作为回礼，双方约定下次再聚，惺惺相别",
[854]="一名凡人为救伤病的母亲在山门长跪不起，<color=#C55A11>{dname1}</color>念其孝心，拿出{item1}给他回去为母亲治病，此人连番拜谢离去。几日后，又拿着{item2}回来，以此传家之宝答谢<color=#C55A11>{dname1}</color>的救母之恩",
[855]="<color=#C55A11>{dname1}</color>手中有一本{item1}，翻来覆去早已看腻了，于是拿到黑市上摆卖，换来一本{item2}，果然内容更加刺激，令其爱不释手",
[856]="<color=#C55A11>{dname1}</color>一日与猫货郎相谈，看其对自己的储物袋十分感兴趣，顿时醒悟拿出其中的{item1}，令猫货郎十分陶醉，当即要出价买下。经过一番讨价还价之后，<color=#C55A11>{dname1}</color>成功从猫货郎手中换得{item2}，得来全不费功夫",
}
